SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2023.Year, Станции2023.NUST, Станции2023.nr, Станции2023.E, Станции2023.EOTP, Станции2023.EURT, Станции2023.EUST, Станции2023.Q, Станции2023.TURT, Станции2023.TUST, Станции2023.B, Станции2023.GAZ, Доп_угли2023.gaz_prir, Доп_угли2023.gazpp, Станции2023.MAZUT, Доп_угли2023.maztop, Доп_угли2023.gtt, Доп_угли2023.nft_proch, Доп_угли2023.disel, Станции2023.TORF, Станции2023.SLAN, Станции2023.ISK_GAZ, Доп_угли2023.domen_g, Доп_угли2023.koks_g, Доп_угли2023.prochgaz, Станции2023.PROCH, Доп_угли2023.tvproch, Доп_угли2023.szh_gaz, Доп_угли2023.inoe, Станции2023.UGOL, Станции2023.DON, Станции2023.PODM, Станции2023.PECH, Доп_угли2023.intin, Доп_угли2023.vork, Станции2023.ARKT, Станции2023.KUZN, Доп_угли2023.kuzngd, Доп_угли2023.kuznt, Доп_угли2023.kuznss, Доп_угли2023.kuznun, Станции2023.URAL, Доп_угли2023.sver, Доп_угли2023.chel, Доп_угли2023.kizel, Станции2023.BASHK, Станции2023.KAN, Доп_угли2023.nazar, Доп_угли2023.ibor, Доп_угли2023.berez, Доп_угли2023.per, Доп_угли2023.irbei, Доп_угли2023.kansk, Станции2023.TUNG, Доп_угли2023.jer, Доп_угли2023.karab, Станции2023.IRKUT, Доп_угли2023.azey, Доп_угли2023.mug, Доп_угли2023.cher, Станции2023.HAK, Станции2023.TUV, Станции2023.BUR, Доп_угли2023.gusin, Доп_угли2023.tugn, Доп_угли2023.okino, Станции2023.CHIT, Доп_угли2023.har, Доп_угли2023.urt, Доп_угли2023.tataur, Доп_угли2023.tarbag, Доп_угли2023.zab_kam, Станции2023.YAKUT, Доп_угли2023.neru, Доп_угли2023.zyryan, Доп_угли2023.pyak, Станции2023.AMUR, Доп_угли2023.rai, Доп_угли2023.erk, Доп_угли2023.ogodj, Станции2023.URG, Станции2023.USHUM, Станции2023.PRIM, Доп_угли2023.bikin, Доп_угли2023.razdol, Доп_угли2023.hankai, Станции2023.MAG, Станции2023.SAH, Станции2023.KAMCH, Станции2023.CHUKOT, Доп_угли2023.anad, Доп_угли2023.bering, Станции2023.KAZAH, Доп_угли2023.ekib, Доп_угли2023.maikub, Доп_угли2023.karag, Доп_угли2023.karajyra, Доп_угли2023.teniz, Станции2023.QOTR, Станции2023.SNK, Станции2023.EWTP, Станции2023.NT, Станции2023.OBOR, Станции2023.VED, Станции2023.OBL, Станции2023.DEP, Станции2023.OES, Станции2023.ER, Станции2023.NUMB1120, Имена_станций.Ведомство AS вед, IIf([вед]=1 Or [вед]=4,1,IIf([вед]=2 Or [вед]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, IIf([OBOR]=20 Or [OBOR]=90,"ГТУ",IIf([OBOR]=21 Or [OBOR]=91,"ПГУ",IIf([OBOR]=22,"Диз",IIf([OBOR]=23,"ГУБТ",IIf([OBOR]=24 Or [OBOR]=89,"ГПА","ПСУ"))))) AS тип, Станции2023.SNt, Имена_станций.n1 AS [мощность блока], IIf([B]>0,[gaz_prir]/[B]*100,0) AS dolya_gaz_prir, IIf([B]>0,[gazpp]/[B]*100,0) AS dolya_gazpp, IIf([B]>0,[UGOL]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[MAZUT]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[TORF]/[B]*100,0) AS dolya_torf, IIf([B]>0,[SLAN]/[B]*100,0) AS dolya_slan, IIf([B]>0,[PROCH]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf([B]>0,IIf([dolya_gaz_prir]>=50,"gaz_prir",IIf([dolya_gazpp]>=50,"gazpp",IIf([dolya_domen_g]>=50,"domen_g",IIf([dolya_koks_g]>=50,"koks_g",IIf([dolya_prochgaz]>=50,"prochgaz",IIf([dolya_ugol]>=50,"ugol",IIf([dolya_mazut]>=50,"neftetopl","prochee"))))))),"net topliva") AS nov_Belyaev, [EUST]/[B] AS [dolya topl na ee], [TUST]/[B] AS [dolya topl na q], Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([Имена_станций.BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved
FROM ((Имена_станций INNER JOIN (Имена_областей RIGHT JOIN (Имена_ОЭС INNER JOIN (Станции2023 LEFT JOIN Доп_угли2023 ON (Станции2023.YEAR = Доп_угли2023.YEAR) AND (Станции2023.NUMB1120 = Доп_угли2023.NUMB1120)) ON Имена_ОЭС.oes = Станции2023.OES) ON Имена_областей.OBL = Станции2023.OBL) ON Имена_станций.NUMB = Станции2023.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) INNER JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code;
